Definition FIVE_SH : Z := 0x800045c0.
Definition KB2 : list reg := [1; 3; 4; 21; 22; 23; 24; 25; 26; 27]%bv.

Lemma five_sh : forall E M, ACONST M -> kentry_ok asegs E M (KWord (SA (ELit 0) FIVE_SH) 1 (ELit 0)).
Proof.
  intros E M HC.
  assert (HIn : In (0x62e00, 8, 32) aglobals) by (unfold aglobals; repeat (solve [left; reflexivity] || right)).
  destruct (ACONST_global M 0x62e00 8 32 HC HIn) as (HA0 & HA8 & HU).
  destruct HU as [B _]. cbn [kentry_ok].
  assert (HS : estart E (SA (ELit 0) FIVE_SH) = 0x800045c0) by (vm_compute; reflexivity).
  split; [lia|]. split; [unfold flat; rewrite HS; lia|].
  rewrite (adenot_of_estart E _ 0x800045c0 HS ltac:(lia)).
  cbn [edenot]. rewrite word_to_le_bytes_1 by lia.
  destruct B as (_ & _ & B). specialize (B 0%nat ltac:(vm_compute; lia)).
  assert (HN : nth_error (global_shadow 8 32) 0 = Some (Z_to_bv 8 0)) by (vm_compute; reflexivity).
  rewrite HN in B.
  replace (Z_to_bv 64 0x800045c0) with (Z_to_bv 64 (sh 0x62e00 + Z.of_nat 0)) by (f_equal; vm_compute; reflexivity).
  apply rdn1_of_mrd. exact B.
Qed.

