Lemma rg_b2_b : forall (x3 x4 x5 x6 x7 x11 x12 x13 x14 x15 x16 x17 x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31 : word)
    (F : bvmap 5 word) (fc : bv 32) (m : mem) (ro : word -> option byte) (ff sph D N lo : Z),
  4 <= N <= 8 -> 1 <= D -> D + N <= 2 ^ 47 ->
  ff mod 64 = 0 -> 0x6e6000 <= ff -> ff + 128 <= 2 ^ 47 ->
  (ff + 128 <= 0x7fff7000 \/ 0x10007fff8000 <= ff) ->
  sph mod 32 = 0 -> 2 ^ 45 <= sph <= 2 ^ 47 ->
  wr_at asegs m ff 128 -> wr_at asegs m (sh ff) 16 -> stk asegs m lo sph -> lo <= sph - 96 -> ff + 128 <= lo ->
  mem_inv asegs m -> ACONST m ->
  exists R' M',
    CatSim.msteps asegs
      (MS (mkR (Z_to_bv 64 CS_SM_RET2) (Z_to_bv 64 (sph - 96)) x3 x4 x5 x6 x7 (Z_to_bv 64 (sph - 16)) (Z_to_bv 64 (sph - 96))
               (Z_to_bv 64 ff) x11 x12 x13 x14 x15 x16 x17 (Z_to_bv 64 D) (Z_to_bv 64 N) (Z_to_bv 64 0x7fff8000)
               x21 x22 x23 x24 x25 x26 x27 x28 x29 x30 x31) F (Z_to_bv 64 CS_SM_RET2) fc None m ro)
      (MS R' F (Z_to_bv 64 LH_HEAD) fc None M' ro)
    /\ getr R' 18 = Z_to_bv 64 (D + (N - 4)) /\ getr R' 16 = Z_to_bv 64 (D + (N - 4)) /\ getr R' 14 = Z_to_bv 64 (4)
    /\ getr R' 20 = Z_to_bv 64 0x7fff8000 /\ getr R' 10 = Z_to_bv 64 ff /\ getr R' 12 = Z_to_bv 64 (sh ff) /\ getr R' 13 = Z_to_bv 64 ff
    /\ getr R' 1 = Z_to_bv 64 CS_SM_RET2 /\ getr R' 2 = Z_to_bv 64 (sph - 96) /\ getr R' 3 = x3 /\ getr R' 4 = x4
    /\ getr R' 8 = Z_to_bv 64 (sph - 16) /\ getr R' 9 = Z_to_bv 64 (sph - 96) /\ getr R' 19 = Z_to_bv 64 N
    /\ getr R' 21 = x21 /\ getr R' 22 = x22 /\ getr R' 23 = x23 /\ getr R' 24 = x24 /\ getr R' 25 = x25 /\ getr R' 26 = x26 /\ getr R' 27 = x27
    /\ munch [(ff, ff + 72); (sh ff, sh ff + 12); (sph - 88, sph - 80)] m M' /\ wmono asegs m M' /\ mem_inv asegs M'
